style:
/* VARIABLES */
:root {
    --main-bg-color: #fec1b5;
    --main-bg-color-light: #f47586;
    --main-bg-color-dark: #f47586;
}
.text-main-color {
    color: var(--main-bg-color);
}
.text-main-color-dark {
    color: var(--main-bg-color-dark);
}
.bg-main-color {
    background-color: var(--main-bg-color);
}
.bg-fill-main-color {
    fill: var(--main-bg-color);
}
.bg-main-color-dark {
    background-color: var(--main-bg-color-dark);
}
.border-main-color {
    border-color: var(--main-bg-color);
}
.bg-gradient-main-color {
    background: linear-gradient(to bottom, var(--main-bg-color-light) 0%, var(--main-bg-color) 100%);
}
.hover\:text-main-color:hover {
    color: var(--main-bg-color);
}
.hover\:bg-main-color:hover {
    background-color: var(--main-bg-color);
}
.hover\:bg-main-color-dark:hover {
    background-color: var(--main-bg-color-dark);
}
.hover\:border-main-color:hover {
    border-color: var(--main-bg-color);
}
.hover\:bg-gradient-main-color:hover {
    background: linear-gradient(to bottom, var(--main-bg-color-light) 0%, var(--main-bg-color) 100%);
}
.focus\:text-main-color:focus {
    color: var(--main-bg-color);
}
.focus\:bg-main-color:focus {
    background-color: var(--main-bg-color);
}
.focus\:border-main-color:focus {
    border-color: var(--main-bg-color);
}
.focus\:bg-gradient-main-color:focus {
    background: linear-gradient(to bottom, var(--main-bg-color-light) 0%, var(--main-bg-color) 100%);
}

/* BASE CLASES PROPIAS */
button[data-action="stop"],
button[data-action="start"] {
    display: none;
}
:focus,
input:focus,
button:hover,
button:focus {
    outline: none;
}
.transition3s {
    transition: all 0.3s ease-in-out;
}
.img::after {
    content: "";
    display: block;
}
.p-1\/10::after {
    content: "";
    display: block;
    padding-top: 100%;
}
.p-1\/15::after {
    content: "";
    display: block;
    padding-top: 150%;
}
.p-1\/20::after {
    content: "";
    display: block;
    padding-top: 200%;
}
.p-1\/7::after {
    content: "";
    display: block;
    padding-top: 70%;
}
.p-1\/6::after {
    content: "";
    display: block;
    padding-top: 60%;
}
.p-1\/5::after {
    content: "";
    display: block;
    padding-top: 50%;
}
.p-1\/4::after {
    content: "";
    display: block;
    padding-top: 40%;
}
.p-1\/3::after {
    content: "";
    display: block;
    padding-top: 30%;
}

.w-screen-4\/12 {
    width: 33.33vw;
}
.w-screen-5\/12 {
    width: 42vw;
}
.w-screen-6\/12 {
    width: 50vw;
}
.max-w-none {
    max-width: none;
}
.last\:border-none > li:last-child,
.last\:border-none > a:last-child {
    border: none !important;
}
.hover\:scale-sm:hover {
    transform: scale(1.1);
}
.hover\:scale-md:hover {
    transform: scale(1.3);
}
.hover\:scale-lg:hover {
    transform: scale(1.5);
}
.rotate-180 {
    transform: rotate(180deg);
}
.filter-white {
    filter: grayscale(100) brightness(0) invert(1);
}
.-z-1 {
    z-index: -1;
}
.social-media li {
    padding: 0px;
}
.social-media li a {
    margin: 0px;
    display: flex;
    width: 100%;
    height: 100%;
}

.swal2-styled.swal2-confirm {
    background-color: var(--main-bg-color-dark);
}
.swal2-styled:focus {
    box-shadow: none;
}
.buscador_oculto {
    margin-top: -60px;
    opacity: 0;
}

@media screen and (min-width: 768px) {
    .md\:p-1\/auto::after {
        display: none !important;
    }
}

