.w-70 {
    width: 17rem;
}

.footer {
    border-radius: 100% 100% 0% 0%;
}

.tns-nav {
    position: absolute;
    width: 100%;
    left: 0;
    bottom: -4rem;
    display: flex;
    justify-content: center;
    z-index: 1;
}

.tns-nav .tns-nav-active {
    background-color: #00dddd;
}

.tns-nav button {
    display: block;
    height: 0.75rem;
    width: 0.75rem;
    background-color: #c5f3f3;
    margin: 0.25rem;
    border-radius: 999px;
}

.tns-nav button:focus {
    outline: none;
}

@media only screen and (max-width: 600px) {
    .footer {
        border-radius: 0%;
    }

    .h-76 {
        height: 16rem;
    }

    .w-76 {
        width: 16rem;
    }
}

